"""Immutable source manifest for six manually inspected external mechanisms."""
import ast
from jev_phase17_common import *
SPECS={
 'Visual-Jev':{'repo':'guanxuyu-sv/Visual-Jev','license':'Apache-2.0','paths':['README.md','REPRODUCE.md','code/vdm/models/vdm_model.py','code/vdm/models/prompts.py','code/vdm/training/train.py','code/vdm/training/losses.py','code/examples/quickstart.py','code/requirements.txt'],'mechanism':'Qwen3-VL visual/public prefix with independent question/options suffixes; full-sequence M-RoPE slicing; attention KV clone; original LM option-token logits, optional typed heads','training':'answer-SFT LoRA a2, original pretrained control, matched typed-head controls; no-new-head does not mean no training','IO':'one image/public context plus question/candidate lists -> masked logits and conditional option distributions','reuse':'LM readout and independently verified prefix/cache execution; offline teacher','not_portable':'K_MAX16 slot limit; Qwen3-VL DeepStack and current transformers API; noncausal public history must be prevented; hardware timings not GMT','adaptation':'real past/current crop montage with provenance; binary compatible/unknown questions and Recall@K; no runtime4B rollout'},
 'Valen':{'repo':'Liuziyu77/Valen','license':'Apache-2.0','paths':['README.md','valen/modeling/dual_encoder/model.py','valen/modeling/dual_encoder/layers.py','valen/modeling/qwen/heads.py','valen/modeling/qwen/batching.py','valen/training/rlcd.py'],'mechanism':'immutable fused state memory; QuestionBlock instruction/state attention; CandidateBlock reads question-specific evidence and shared projected state KV; candidate chunks retain order; shared scalar head','training':'SFT and explicit experimental GRPO-like RLCD with detached group rollouts, correctness/confidence reward, clipping, optional KL/Brier','IO':'compiled shared state, typed questions, candidate token spans -> variable length candidate logits','reuse':'state/question/candidate decomposition and chunks preserving candidate identity','not_portable':'new task heads and task training required; Qwen branch batching does not itself prove shared-prefix KV; not commercial TypeSafe architecture','adaptation':'typed WHO/OWNER/WRITE/OLD_OR_NEW with legal IDs; separate evidence and ownership reliability; compare ordinary Attention same evidence'},
 'OneJev':{'repo':'OmniJev/OneJev','license':'Apache-2.0','paths':['qev/engine.py','qev/mm_engine.py','qev/prompt.py','qev/schema.py','qev/calibrate.py'],'mechanism':'LM option readout; longest-common token prefix; deepcopy/fork attention KV plus conv/recurrent layer states; sequential fallback on fork/parity/OOM; cyclic order averaging; chunk-plus-none choices','training':'inference library with primitive/K temperature calibration, not task learning proof','IO':'typed request state/questions -> Choice/Noul/Score distributions plus diagnostics','reuse':'hybrid-state fork, memory bounds, rejection, temperature and calibration metrics','not_portable':'chunk merger uses none mass heuristic; no guaranteed global posterior calibration. MM preparation key uses object identity, unsafe for in-place identity history mutation unless invalidated','adaptation':'hash video/frame/camera/history/model/prompt/state version; reject unknown cache type; independently test chunk comparability instead of comparing softmaxes'},
 'Jev-Mem':{'repo':'libingzheren/Jev-Mem','license':'MIT','paths':['memory/jev_mem_retrieval.py','memory/jev_mem_policies.py','memory/jev_questions.py','memory/jev_client.py'],'mechanism':'existing MAGMA graph/vector retrieval; separate admission/type, candidate relation and stopping questions; real evidence traversal with node/edge/depth/call/deadline budgets; content-hash response cache','training':'SDK/optional local backend; no identity tracking checkpoint here; mock fixtures explicitly labelled','IO':'stored observation/graph query plus actual retrieved candidates -> probabilities, graph routes and retrieved evidence','reuse':'keep source observations separate from association read view; query budgets and auditable fallback','not_portable':'text semantic entities and narrative timestamps are not GlobalID certification; remote service not authorised deployment','adaptation':'raw append-only Gallery plus reversible weights and source indices; appearance consistency distinct from owner correctness'},
 'NanoJev':{'repo':'TianyuCodings/NanoJev','license':'MIT','paths':['scripts/train_toy_decisions.py','scripts/train_unified_games.py','scripts/unified_game_pipeline.py','scripts/calibrated_objectives.py'],'mechanism':'candidate semantic leaf paths; one padded backbone forward, shared scalar with optional candidate set attention, Boolean sigmoid / choice softmax; no generative decoding','training':'gold/valid teacher-distribution CE; unified policy and actual environment outcome roles; lagged-model Expected SARSA distinct from actual outcomes','IO':'state/task/candidate action descriptions -> categorical/Boolean probabilities; environment execution supplies outcome data','reuse':'target eligibility, action/outcome role separation, permutation tests and bounded execution feedback','not_portable':'toy game transitions are not ownership labels or joint Hungarian utility; train_toy forward repeats prefix, sharing is separate optimisation','adaptation':'do not equate local edge utility to joint assignment; actual executed branch outcomes and unknown/censored masks'},
 'vllm-jev':{'repo':'mode-io/vllm-jev','license':'Apache-2.0','paths':['vllm_jev/decision.py','vllm_jev/endpoint.py','vllm_jev/prefix_components.py','vllm_jev/online_prefix.py','vllm_jev/precision.py','vllm_jev/vjev_export.py'],'mechanism':'AsyncLLM encode pooling at readout positions; semaphore/compile lock, within-request dedup tasks and cancellation; request random salt; optional full/Mamba prefix eviction with active ref protection','training':'export/serving different public heads; not an identity-learning algorithm','IO':'validated requests/model templates -> logits/probabilities plus token/runtime usage','reuse':'tenant salt, cache version, correct hybrid-component invalidation, cancellation and cold/warm accounting','not_portable':'version-sensitive private vLLM scheduler hooks; dedicated runtime required; acceleration alone no scientific benefit','adaptation':'serve offline teacher first; numerical/commit parity before replacing native execution; separately time total batch and amortized question'}}
def main():
 protect();entries=[]
 for name,spec in SPECS.items():
  root=OUT/'external'/name;head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip();files=[]
  for rel in spec['paths']:
   p=root/rel;assert p.is_file(),p;funcs=[]
   if p.suffix=='.py':
    tree=ast.parse(p.read_text());funcs=[{'name':n.name,'line':n.lineno} for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))]
   files.append(dict(path=rel,SHA256=sha(p),core_functions=funcs,reading_scope='source inspected, not merely README'))
  licenses=[ref(p) for p in root.glob('LICENSE*') if p.is_file()]
  entries.append(dict(name=name,commit=head,url='https://github.com/'+spec['repo'],source_path=str(root),files=files,license_files=licenses,**spec))
 save(REPORTS/'EXTERNAL_CODE_MANIFEST.json',dict(status='COMPLETE_SOURCE_AUDIT',binding=binding(),repositories=entries,runtime_reproduction_status='NOT_YET_RUN',commercial_Jev_replication_claim=False))
 matrix=['# External architecture matrix','', '|Repository|Frozen SHA|Readout and execution|MCMOT limitation|','|---|---|---|---|']
 for e in entries:matrix.append('|'+e['name']+'|`'+e['commit']+'`|'+e['mechanism']+'|'+e['not_portable']+'|')
 matrix+=['','All file hashes, core function lines, licences, I/O, training and adaptations are in EXTERNAL_CODE_MANIFEST.json. These are inspected source mechanisms; no benchmark result is reproduced by reading code.']
 (ROOT/'docs/PHASE17_EXTERNAL_ARCHITECTURE_MATRIX.md').write_text('\n'.join(matrix)+'\n')
 reg=read(MASTER/'EXPERIMENT_REGISTRY.json');e=reg['experiments'][0];e.update(status='COMPLETE',evidence=[ref(REPORTS/'EXTERNAL_CODE_MANIFEST.json')]);save(MASTER/'EXPERIMENT_REGISTRY.json',reg)
 evidence=read(MASTER/'EVIDENCE_REGISTRY.json');evidence['entries'] += [ref(REPORTS/'EXTERNAL_CODE_MANIFEST.json')];save(MASTER/'EVIDENCE_REGISTRY.json',evidence)
 print('SIX_EXTERNAL_SOURCE_AUDITS_COMPLETE',[(e['name'],e['commit']) for e in entries])
if __name__=='__main__':main()
